define('taoQtiItem/qtiCreator/widgets/static/text/states/Sleep',['context', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/static/states/Sleep', 'taoQtiItem/qtiCreator/editor/gridEditor/content'], function (context, stateFactory, SleepState, contentHelper) {
  var DISABLE_FIGURE_WIDGET = context.featureFlags && context.featureFlags.FEATURE_FLAG_DISABLE_FIGURE_WIDGET;
  var TextBlockStateSleep = stateFactory.extend(SleepState, function () {
    var widget = this.widget;
    widget.afterStateExit(function (e, element, state) {
      var serial = element.getSerial();
      if (state.name === 'active' && serial !== widget.serial && (element.qtiClass === 'include' || !DISABLE_FIGURE_WIDGET && element.qtiClass === 'figure')) {
        var composingElts = widget.element.getComposingElements();
        if (composingElts[serial]) {
          var $pseudoContainer = $('<div>').html(widget.$container.find('[data-html-editable="true"]').html());
          var newBody = contentHelper.getContent($pseudoContainer);
          var container = widget.element;
          container.body(newBody);
        }
      }
    }, 'question');
  }, function () {
    this.widget.offEvents('question');
  });
  return TextBlockStateSleep;
});
