define('taoQtiItem/qtiCreator/widgets/interactions/states/Custom',['taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Custom', 'tpl!taoQtiItem/qtiCreator/tpl/notifications/widgetOverlay', 'i18n', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/answerState'], function (stateFactory, Custom, overlayTpl, __, answerState) {
  var InteractionStateCustom = stateFactory.create(Custom, function () {
    this.widget.$container.append(overlayTpl({
      message: __('Custom Response Processing Mode')
    }));
    this.widget.$container.find('[data-edit=map], [data-edit=correct]').hide();
  }, function () {
    answerState.createOutcomeScore(this.widget);
    this.widget.$container.children('.overlay').remove();
  });
  return InteractionStateCustom;
});
