define('taoQtiItem/qtiCreator/widgets/interactions/graphicAssociateInteraction/states/Question',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCommonRenderer/helpers/Graphic', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/interactions/blockInteraction/states/Question', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/graphicInteractionShapeEditor', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/imageSelector', 'taoQtiItem/qtiCreator/widgets/helpers/formElement', 'taoQtiItem/qtiCreator/widgets/component/minMax/minMax', 'taoQtiItem/qtiCreator/widgets/helpers/identifier', 'taoQtiItem/qtiCreator/widgets/interactions/graphicAssociateInteraction/helpers/arrowMode', 'tpl!taoQtiItem/qtiCreator/tpl/forms/interactions/graphicAssociate', 'tpl!taoQtiItem/qtiCreator/tpl/forms/choices/associableHotspot', 'taoQtiItem/qtiCreator/helper/panel', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/bgImage'], function ($, _, __, GraphicHelper, stateFactory, Question, shapeEditor, imageSelector, formElement, minMaxComponentFactory, identifierHelper, arrowModeHelper, formTpl, choiceFormTpl, panel, bgImage) {
  'use strict';
  function initQuestionState() {
    var widget = this.widget;
    var interaction = widget.element;
    var paper = interaction.paper;
    var $choiceForm = widget.choiceForm;
    var $formInteractionPanel = $('#item-editor-interaction-property-bar');
    var $formChoicePanel = $('#item-editor-choice-property-bar');
    var $left, $top, $width, $height;
    var activeChoiceSerial = null;
    function detachChoiceThresholdHandler() {
      if (_.isFunction(widget.off) && _.isFunction(widget._choiceThresholdHandler)) {
        widget.off('choiceCreated choiceDeleted', widget._choiceThresholdHandler);
        widget._choiceThresholdHandler = null;
      }
    }
    if (!paper) {
      return;
    }
    widget._editor = shapeEditor(widget, {
      shapeCreated: function shapeCreated(shape, type) {
        var newChoice = interaction.createChoice({
          shape: type === 'path' ? 'poly' : type,
          coords: GraphicHelper.qtiCoords(shape)
        });
        shape.id = newChoice.serial;
        if (arrowModeHelper.isArrowMode(interaction)) {
          arrowModeHelper.ensureChoiceDirectionDefaults(newChoice);
        }
      },
      shapeRemoved: function shapeRemoved(id) {
        interaction.removeChoice(id);
      },
      enterHandling: function enterHandling(shape) {
        enterChoiceForm(shape.id);
      },
      quitHandling: function quitHandling() {
        leaveChoiceForm();
      },
      shapeChange: function shapeChange(shape) {
        var choice = interaction.getChoice(shape.id);
        if (choice) {
          choice.attr('coords', GraphicHelper.qtiCoords(shape, paper, interaction.object.attr('width')));
          if ($left && $left.length) {
            var bbox = shape.getBBox();
            $left.val(parseInt(bbox.x, 10));
            $top.val(parseInt(bbox.y, 10));
            $width.val(parseInt(bbox.width, 10));
            $height.val(parseInt(bbox.height, 10));
          }
        }
      }
    });
    widget._editor.create();
    function enterChoiceForm(serial) {
      var choice = interaction.getChoice(serial);
      if (choice) {
        var element = interaction.paper.getById(serial);
        var bbox = element.getBBox();
        var direction = arrowModeHelper.getChoiceDirection(choice);
        $choiceForm.empty().html(choiceFormTpl({
          identifier: choice.id(),
          fixed: choice.attr('fixed'),
          serial: serial,
          arrowMode: arrowModeHelper.isArrowMode(interaction),
          startEnabled: direction.start,
          endEnabled: direction.end,
          x: parseInt(bbox.x, 10),
          y: parseInt(bbox.y, 10),
          width: parseInt(bbox.width, 10),
          height: parseInt(bbox.height, 10)
        }));
        minMaxComponentFactory($choiceForm.find('.min-max-panel'), {
          min: {
            fieldName: 'matchMin',
            value: _.parseInt(choice.attr('matchMin')) || 0,
            helpMessage: __('The minimum number of choices this choice must be associated with to form a valid response.')
          },
          max: {
            fieldName: 'matchMax',
            value: _.parseInt(choice.attr('matchMax')) || 0,
            helpMessage: __('The maximum number of choices this choice may be associated with.')
          },
          upperThreshold: _.size(interaction.getChoices())
        }).on('render', function () {
          detachChoiceThresholdHandler();
          widget._choiceThresholdHandler = data => {
            if (data.interaction.serial === interaction.serial) {
              this.updateThresholds(1, _.size(interaction.getChoices()));
            }
          };
          widget.on('choiceCreated choiceDeleted', widget._choiceThresholdHandler);
        });
        formElement.initWidget($choiceForm);
        var callbacks = formElement.getMinMaxAttributeCallbacks('matchMin', 'matchMax');
        callbacks.identifier = identifierHelper.updateChoiceIdentifier;
        callbacks.fixed = formElement.getAttributeChangeCallback();
        callbacks['data-start'] = function (choiceElement, value) {
          var current = arrowModeHelper.getChoiceDirection(choiceElement);
          arrowModeHelper.setChoiceDirection(choiceElement, value === true, current.end);
        };
        callbacks['data-end'] = function (choiceElement, value) {
          var current = arrowModeHelper.getChoiceDirection(choiceElement);
          arrowModeHelper.setChoiceDirection(choiceElement, current.start, value === true);
        };
        formElement.setChangeCallbacks($choiceForm, choice, callbacks);
        $formChoicePanel.show();
        panel.openSections($formChoicePanel.children('section'));
        panel.closeSections($formInteractionPanel.children('section'));
        $left = $('input[name=x]', $choiceForm);
        $top = $('input[name=y]', $choiceForm);
        $width = $('input[name=width]', $choiceForm);
        $height = $('input[name=height]', $choiceForm);
        activeChoiceSerial = serial;
        widget._activeChoiceSerial = serial;
      }
    }
    function leaveChoiceForm() {
      if ($formChoicePanel.css('display') !== 'none') {
        detachChoiceThresholdHandler();
        panel.openSections($formInteractionPanel.children('section'));
        $formChoicePanel.hide();
        $choiceForm.empty();
        activeChoiceSerial = null;
        widget._activeChoiceSerial = null;
      }
    }
    widget._enterChoiceForm = enterChoiceForm;
  }
  function exitQuestionState() {
    var widget = this.widget;
    var interaction = widget.element;
    var paper = interaction.paper;
    var valid = !!interaction.object.attr('data') && !_.isEmpty(interaction.choices);
    widget.isValid('graphicAssociateInteraction', valid);
    if (!paper) {
      return;
    }
    $(window).off('resize.changestate');
    if (widget._editor) {
      widget._editor.destroy();
    }
    if (_.isFunction(widget.off) && _.isFunction(widget._choiceThresholdHandler)) {
      widget.off('choiceCreated choiceDeleted', widget._choiceThresholdHandler);
      widget._choiceThresholdHandler = null;
    }
    widget._enterChoiceForm = null;
    widget._activeChoiceSerial = null;
    $('.image-editor.solid, .block-listing.source', this.widget.$container).css('min-width', 0);
  }
  var GraphicAssociateInteractionStateQuestion = stateFactory.extend(Question, initQuestionState, exitQuestionState);
  GraphicAssociateInteractionStateQuestion.prototype.initForm = function initForm() {
    var widget = this.widget;
    var options = widget.options;
    var interaction = widget.element;
    var $form = widget.$form;
    var getMaxPairs = function getMaxPairs(choices) {
      var pairs = 0;
      if (choices > 0) {
        return Math.round(choices * (choices - 1) / 2);
      }
      return pairs;
    };
    $form.html(formTpl({
      baseUrl: options.baseUrl,
      data: interaction.object.attr('data'),
      width: interaction.object.attr('width'),
      height: interaction.object.attr('height'),
      type: interaction.object.attr('type'),
      arrowMode: arrowModeHelper.isArrowMode(interaction)
    }));
    minMaxComponentFactory($form.find('.min-max-panel'), {
      min: {
        fieldName: 'minAssociations',
        value: _.parseInt(interaction.attr('minAssociations')) || 0,
        helpMessage: __('The minimum number of associations that the candidate is required to make to form a valid response.')
      },
      max: {
        fieldName: 'maxAssociations',
        value: _.parseInt(interaction.attr('maxAssociations')) || 0,
        helpMessage: __('The maximum number of associations that the candidate is allowed to make.')
      },
      upperThreshold: getMaxPairs(_.size(interaction.getChoices()))
    }).on('render', function () {
      widget.on('choiceCreated choiceDeleted', data => {
        if (data.interaction.serial === interaction.serial) {
          this.updateThresholds(1, getMaxPairs(_.size(interaction.getChoices())));
        }
      });
    });
    imageSelector($form, options);
    formElement.initWidget($form);
    bgImage.setupImage(widget);
    var callbacks = formElement.getMinMaxAttributeCallbacks('minAssociations', 'maxAssociations');
    callbacks['data-interaction-subtype'] = function (element, value) {
      var isEnabled = arrowModeHelper.setArrowMode(element, value === 'arrow');
      if (widget._activeChoiceSerial && _.isFunction(widget._enterChoiceForm)) {
        widget._enterChoiceForm(widget._activeChoiceSerial);
      }
      if (isEnabled !== (value === 'arrow')) {
        widget.$form.find('[name="data-interaction-subtype"][value="' + (isEnabled ? 'arrow' : 'line') + '"]').prop('checked', true);
      }
    };
    bgImage.setChangeCallbacks(widget, formElement, callbacks);
  };
  return GraphicAssociateInteractionStateQuestion;
});
