define('taoQtiItem/qtiCreator/helper/rubyTagCleaner',[], function () {
  'use strict';

  var rubyTagCleaner = {
    clean(htmlContent) {
      if (!htmlContent) {
        return htmlContent;
      }
      var tempDiv = document.createElement('div');
      tempDiv.innerHTML = htmlContent;
      var rubyElements = [];
      var allElements = tempDiv.getElementsByTagName('*');
      for (var i = 0; i < allElements.length; i++) {
        var tagName = allElements[i].tagName.toLowerCase();
        if (tagName === 'qh5:ruby' || tagName === 'ruby') {
          rubyElements.push(allElements[i]);
        }
      }
      rubyElements.forEach(function (ruby) {
        var rbElements = [];
        var rtElements = [];
        var children = ruby.children;
        for (var _i = 0; _i < children.length; _i++) {
          var _tagName = children[_i].tagName.toLowerCase();
          if (_tagName === 'qh5:rb' || _tagName === 'rb') {
            rbElements.push(children[_i]);
          } else if (_tagName === 'qh5:rt' || _tagName === 'rt') {
            rtElements.push(children[_i]);
          }
        }
        var shouldRemove = false;
        if (rbElements.length === 0) {
          shouldRemove = true;
        } else if (rtElements.length === 0) {
          shouldRemove = true;
        } else if (rtElements.length > 0) {
          var hasNonEmptyRt = false;
          for (var j = 0; j < rtElements.length; j++) {
            var raw = rtElements[j].textContent || '';
            var normalized = raw.replace(/[\s\u00A0\u200B\uFEFF\u3000]+/g, '');
            if (normalized !== '') {
              hasNonEmptyRt = true;
              break;
            }
          }
          if (!hasNonEmptyRt) {
            shouldRemove = true;
          }
        }
        if (shouldRemove && rbElements.length > 0) {
          var baseText = rbElements.map(rb => rb.textContent || '').join('');
          var textNode = document.createTextNode(baseText);
          ruby.parentNode.replaceChild(textNode, ruby);
        } else if (shouldRemove) {
          ruby.remove();
        }
      });
      return tempDiv.innerHTML;
    }
  };
  return rubyTagCleaner;
});
