    var onReverse = _.isFunction(opts.onReverse) ? opts.onReverse : _.noop;
    var paper = interaction.paper;
    var selectedLeftId = null;
    var selectedRightId = null;
    var controlGroup;
    var controlHitbox;
    var controlBg;
    var controlPath;
